UISprayCanParticle=function(game,x,y){Phaser.Particle.call(this,game,x,y,game.cache.getBitmapData('spray'+UISprayCanParticle.currentEmitter));this.kill();};UISprayCanParticle.prototype=Object.create(Phaser.Particle.prototype);UISprayCanParticle.prototype.constructor=UISprayCanParticle;UISprayCanParticle.prototype.update=function(){this.alpha=Math.max(0.0,this.alpha-(0.01-Math.random()*0.004));this.scale.set(this.scale.x+0.0125,this.scale.y+0.0125);};UISprayCanParticle.prototype.retire=function(){this.kill();};UISprayCanParticle.setCurrentEmitter=function(currentEmitter){UISprayCanParticle.currentEmitter=currentEmitter};UISprayCanParticle.setColour=function(game,colour){var spray=game.cache.getBitmapData('spray'+UISprayCanParticle.currentEmitter);spray.clear();var radGrad=spray.context.createRadialGradient(UIConstants.SPRAY_RADIUS,UIConstants.SPRAY_RADIUS,UIConstants.SPRAY_INNER_RADIUS,UIConstants.SPRAY_RADIUS,UIConstants.SPRAY_RADIUS,UIConstants.SPRAY_RADIUS);var rgbColour=Utils.hexToRGB(colour.numericValue);radGrad.addColorStop(0,'rgba('+rgbColour.r+', '+rgbColour.g+', '+rgbColour.b+', 1)');radGrad.addColorStop(1,'rgba('+rgbColour.r+', '+rgbColour.g+', '+rgbColour.b+', 0)');spray.context.fillStyle=radGrad;spray.context.fillRect(0,0,UIConstants.SPRAY_RADIUS*2,UIConstants.SPRAY_RADIUS*2);spray.dirty=true;};